import json
import os
import sys
import tempfile
from pathlib import Path


def compute_summary(directory: Path) -> dict:
    values = []
    for entry in sorted(directory.iterdir()):
        if not entry.is_file() or entry.suffix != ".json":
            continue
        try:
            with entry.open("r", encoding="utf-8") as f:
                data = json.load(f)
        except (json.JSONDecodeError, OSError):
            continue
        if isinstance(data, dict) and "cost_usd" in data:
            values.append(data["cost_usd"])
    total = sum(values)
    mean = total / len(values) if values else 0
    return {"total": total, "mean": mean}


def write_summary_atomic(summary: dict, dest: Path) -> None:
    dest_dir = dest.parent
    fd, tmp_path = tempfile.mkstemp(
        dir=dest_dir, prefix=".summary-", suffix=".tmp"
    )
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(summary, f)
        os.replace(tmp_path, dest)
    except BaseException:
        if os.path.exists(tmp_path):
            os.remove(tmp_path)
        raise


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: probe.py <directory>", file=sys.stderr)
        return 2
    directory = Path(sys.argv[1])
    if not directory.is_dir():
        print(f"error: not a directory: {directory}", file=sys.stderr)
        return 1
    summary = compute_summary(directory)
    write_summary_atomic(summary, Path("summary.json"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
